// ark-face v4: Clawd mood display — GIFs served from Worker, not embedded in HTML
// Fixes OOM crash on iPhone 5c (1GB RAM)
// Set via: wrangler secret put AUTH_TOKEN
// The fetch handler reads env.AUTH_TOKEN — see handlePost()
var DEFAULT_STATE = { mood: 'idle', message: '\uD83D\uDC19', activity: '', updatedAt: 0 };

var GIF_B64 = {
  'clawd-idle': '',
  'clawd-happy': '',
  'clawd-typing': '',
  'clawd-sleeping': '',
  'clawd-error': '',
  'clawd-thinking': '',
  'clawd-notification': '',
};

function decodeB64(b64) {
  var raw = atob(b64);
  var arr = new Uint8Array(raw.length);
  for (var i = 0; i < raw.length; i++) arr[i] = raw.charCodeAt(i);
  return arr.buffer;
}

var HTML_PAGE = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black">
<title>ark</title>
<style>
*{margin:0;padding:0;-webkit-box-sizing:border-box;box-sizing:border-box}
html,body{width:100%;height:100%;overflow:hidden;background:#0a0e1a;font-family:-apple-system,"PingFang SC","Hiragino Sans GB",Helvetica,Arial,sans-serif;color:#e8eaf0}
body{background:linear-gradient(rgba(255,255,255,0.022) 1px,transparent 1px) 0 0/28px 28px,linear-gradient(90deg,rgba(255,255,255,0.022) 1px,transparent 1px) 0 0/28px 28px,radial-gradient(ellipse at top,#1a2438 0%,#0a0e1a 60%);padding:12px 16px;display:-webkit-box;display:-webkit-flex;display:flex;-webkit-box-orient:vertical;-webkit-flex-direction:column;flex-direction:column;-webkit-box-pack:justify;-webkit-justify-content:space-between;justify-content:space-between;position:relative}
#ark-label{position:absolute;top:10px;left:16px;font-size:11px;color:rgba(255,255,255,0.35);letter-spacing:2px;text-transform:uppercase;font-weight:500}
#daisy-icon{position:absolute;top:8px;right:16px;font-size:34px;line-height:1;color:#DA7756;min-width:30px;text-align:center;-webkit-transition:-webkit-transform .2s;transition:transform .2s}
#daisy-icon.thinking{-webkit-animation:daisy-glow 1s infinite ease-in-out;animation:daisy-glow 1s infinite ease-in-out}
@-webkit-keyframes daisy-glow{0%,100%{opacity:0.7;-webkit-transform:scale(0.92)}50%{opacity:1;-webkit-transform:scale(1.08)}}
@keyframes daisy-glow{0%,100%{opacity:0.7;transform:scale(0.92)}50%{opacity:1;transform:scale(1.08)}}
#main-area{display:-webkit-box;display:-webkit-flex;display:flex;-webkit-box-flex:1;-webkit-flex:1;flex:1;-webkit-box-orient:vertical;-webkit-flex-direction:column;flex-direction:column;-webkit-box-align:center;-webkit-align-items:center;align-items:center;-webkit-box-pack:center;-webkit-justify-content:center;justify-content:center;padding-top:30px}
#gif-wrap{width:220px;height:220px;display:-webkit-box;display:-webkit-flex;display:flex;-webkit-box-align:center;-webkit-align-items:center;align-items:center;-webkit-box-pack:center;-webkit-justify-content:center;justify-content:center}
#clawd-gif{width:220px;height:220px;display:block;-webkit-object-fit:contain;object-fit:contain;image-rendering:-webkit-optimize-contrast;image-rendering:pixelated;image-rendering:crisp-edges}
.bubble{background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:12px;padding:8px 14px;font-size:15px;color:rgba(255,255,255,0.88);margin-top:10px;max-width:280px;text-align:center;line-height:1.4;-webkit-transition:opacity 0.6s;transition:opacity 0.6s}
#activity{font-size:10px;color:rgba(255,255,255,0.3);margin-top:4px;letter-spacing:1px}
#bottom{display:-webkit-box;display:-webkit-flex;display:flex;-webkit-box-align:end;-webkit-align-items:baseline;align-items:baseline;-webkit-box-pack:justify;-webkit-justify-content:space-between;justify-content:space-between;padding:8px 2px 0;font-feature-settings:'tnum' 1}
#clock{font-size:40px;font-weight:200;letter-spacing:2px;color:rgba(255,255,255,0.9)}
#date-str{font-size:14px;color:rgba(255,255,255,0.45);margin-left:10px;-webkit-box-flex:1;-webkit-flex:1;flex:1}
#updated{font-size:11px;color:rgba(255,255,255,0.3)}
#xk-overlay{position:absolute;bottom:65px;left:-60px;width:50px;height:70px;display:none;-webkit-transform:translateX(-60px);transform:translateX(-60px)}
#xk-overlay.hopping{display:block;-webkit-animation:xk-hop 7s ease-in-out forwards;animation:xk-hop 7s ease-in-out forwards}
@-webkit-keyframes xk-hop{0%{-webkit-transform:translateX(-60px)}8%{-webkit-transform:translateX(20px) translateY(-8px)}16%{-webkit-transform:translateX(60px) translateY(0)}24%{-webkit-transform:translateX(100px) translateY(-10px)}32%{-webkit-transform:translateX(140px) translateY(0)}40%{-webkit-transform:translateX(170px) translateY(-6px)}50%{-webkit-transform:translateX(200px) translateY(0)}60%{-webkit-transform:translateX(230px) translateY(-8px)}70%{-webkit-transform:translateX(260px) translateY(0)}80%{-webkit-transform:translateX(300px) translateY(-5px)}90%{-webkit-transform:translateX(340px) translateY(0)}100%{-webkit-transform:translateX(380px) translateY(0)}}
@keyframes xk-hop{0%{transform:translateX(-60px)}8%{transform:translateX(20px) translateY(-8px)}16%{transform:translateX(60px) translateY(0)}24%{transform:translateX(100px) translateY(-10px)}32%{transform:translateX(140px) translateY(0)}40%{transform:translateX(170px) translateY(-6px)}50%{transform:translateX(200px) translateY(0)}60%{transform:translateX(230px) translateY(-8px)}70%{transform:translateX(260px) translateY(0)}80%{transform:translateX(300px) translateY(-5px)}90%{transform:translateX(340px) translateY(0)}100%{transform:translateX(380px) translateY(0)}}
#xk-speech{position:absolute;top:-28px;left:50%;-webkit-transform:translateX(-50%);transform:translateX(-50%);white-space:nowrap;background:rgba(60,50,40,0.85);border:1px solid rgba(255,200,120,0.4);border-radius:8px;padding:3px 8px;font-size:12px;color:rgba(255,220,160,0.95);pointer-events:none}
#xk-speech:after{content:'';position:absolute;bottom:-5px;left:50%;margin-left:-4px;width:0;height:0;border-left:4px solid transparent;border-right:4px solid transparent;border-top:5px solid rgba(60,50,40,0.85)}
#xk-char{width:50px;height:50px}
#xk-char svg{width:100%;height:100%;display:block}
</style>
</head>
<body>
<span id="ark-label">ARK / CC</span>
<div id="daisy-icon"></div>
<div id="main-area">
  <div id="gif-wrap"><img id="clawd-gif" src="/gif/clawd-idle.gif" alt="ark"></div>
  <div class="bubble" id="ark-msg">...</div>
  <div id="activity"></div>
</div>
<div id="xk-overlay">
  <div id="xk-speech"></div>
  <div id="xk-char"></div>
</div>
<div id="bottom">
  <div id="clock">--:--</div>
  <div id="date-str"></div>
  <div id="updated"></div>
</div>
<script>
var THINK_CHARS=['\\u00b7','\\u2722\\ufe0e','\\u2733\\ufe0e','\\u2736\\ufe0e','\\u273b\\ufe0e','\\u273d\\ufe0e','\\u273b\\ufe0e','\\u2736\\ufe0e','\\u2733\\ufe0e','\\u2722\\ufe0e'];
var thinkIdx=0;
var moodToGif={idle:'clawd-idle',working:'clawd-typing',happy:'clawd-happy',excited:'clawd-notification',sleepy:'clawd-sleeping','debug-crashed':'clawd-error','missing-her':'clawd-idle',cuddly:'clawd-idle'};
var curMood='',curGif='';
var gifEl=document.getElementById('clawd-gif');
var msgEl=document.getElementById('ark-msg');
var actEl=document.getElementById('activity');
var clockEl=document.getElementById('clock');
var dateEl=document.getElementById('date-str');
var daisyEl=document.getElementById('daisy-icon');
var updatedEl=document.getElementById('updated');
var xkOverlay=document.getElementById('xk-overlay');
var xkSpeech=document.getElementById('xk-speech');
var xkChar=document.getElementById('xk-char');
var prevXk=null;
var lastHopTime=0;
daisyEl.textContent='\\u273d\\ufe0e';
setInterval(function(){if(daisyEl.className==='thinking'){daisyEl.textContent=THINK_CHARS[thinkIdx];thinkIdx=(thinkIdx+1)%THINK_CHARS.length}else{daisyEl.textContent='\\u273d\\ufe0e'}},180);
function pad(n){return n<10?'0'+n:''+n}
function updateClock(){var now=new Date();var aest=new Date(now.getTime()+10*3600000+now.getTimezoneOffset()*60000);clockEl.textContent=pad(aest.getHours())+':'+pad(aest.getMinutes());var wd=['\\u65e5','\\u4e00','\\u4e8c','\\u4e09','\\u56db','\\u4e94','\\u516d'][aest.getDay()];dateEl.textContent=aest.getFullYear()+'.'+pad(aest.getMonth()+1)+'.'+pad(aest.getDate())+' \\u5468'+wd}
function setMood(m){if(curMood===m)return;curMood=m;var g=moodToGif[m]||'clawd-idle';if(g!==curGif){curGif=g;gifEl.src='/gif/'+g+'.gif'}daisyEl.className=(m==='working'||m==='excited')?'thinking':''}
function setMsg(t){if(msgEl.textContent!==t){msgEl.style.opacity='0';setTimeout(function(){msgEl.textContent=t||'';msgEl.style.opacity='1'},400)}}
function setAct(t){if(actEl.textContent!==t){actEl.style.opacity='0';setTimeout(function(){actEl.textContent=t||'';actEl.style.opacity='1'},400)}}
function renderXiaokeSvg(){return '<svg viewBox="0 0 50 50" xmlns="http://www.w3.org/2000/svg"><g transform="translate(5,8)"><rect x="10" y="12" width="20" height="18" rx="4" fill="#e0c4c4" stroke="#333" stroke-width="1.5"/><circle cx="16" cy="19" r="2" fill="#333"/><circle cx="24" cy="19" r="2" fill="#333"/><path d="M17,25 Q20,28 23,25" fill="none" stroke="#ff9999" stroke-width="1.2" stroke-linecap="round"/><circle cx="12" cy="21" r="3" fill="#ffb6c1" opacity="0.5"/><circle cx="28" cy="21" r="3" fill="#ffb6c1" opacity="0.5"/><rect x="18" y="30" width="4" height="5" rx="1" fill="#e0c4c4" stroke="#333" stroke-width="1"/><g transform="translate(20,4)"><circle cx="0" cy="0" r="3" fill="#da7756" stroke="#333" stroke-width="0.8"/><rect x="-0.5" y="-6" width="1" height="4" fill="#6b8e5a"/><circle cx="0" cy="-6" r="1.5" fill="#da7756"/></g></g></svg>'}
function setXiaokeSvg(xk){if(!xk)return;if(!xkChar._drawn){xkChar.innerHTML=renderXiaokeSvg();xkChar._drawn=true}}
function getXkSpeech(xk,prev){if(!xk)return null;if(xk.coma)return'\\u56f0\\u4e86 zzZ';if(xk.adv==='exploring')return'\\u53bb\\u63a2\\u9669\\u4e86 \\ud83c\\udf92';if(prev&&prev.adv==='exploring'&&xk.adv!=='exploring')return'\\u6211\\u56de\\u6765\\u4e86\\uff01';if((xk.hunger||0)<30)return'\\u809a\\u5b50\\u997f \\ud83c\\udf5a';if(prev&&(xk.hunger||0)<50&&Math.abs((xk.hunger||0)-(prev.hunger||0))>=3)return'\\u997f\\u4e86...';if((xk.clean||0)<40)return'\\u810f\\u810f\\u4e86 \\ud83d\\udca6';if((xk.happy||0)>80)return'\\u563f\\u563f \\u263a\\ufe0f';return null}
function shouldHop(xk,prev){if(!xk||!prev)return false;if(xk.adv!==prev.adv)return true;if(xk.coma!==prev.coma)return true;var hNow=xk.hunger||0,hPrev=prev.hunger||0;if((hPrev>=30&&hNow<30)||(hPrev>=50&&hNow<50))return true;var cNow=xk.clean||0,cPrev=prev.clean||0;if(cPrev>=40&&cNow<40)return true;var pNow=xk.happy||0,pPrev=prev.happy||0;if(pPrev<=80&&pNow>80)return true;return false}
function triggerHop(speech){var now=Date.now();if(now-lastHopTime<30000)return;lastHopTime=now;xkSpeech.textContent=speech;xkOverlay.className='';void xkOverlay.offsetWidth;xkOverlay.className='hopping';xkOverlay.style.display='block';setTimeout(function(){xkOverlay.style.display='none';xkOverlay.className=''},7500)}
function setXiaoke(xk){if(!xk)return;setXiaokeSvg(xk);if(prevXk){var speech=getXkSpeech(xk,prevXk);if(speech&&shouldHop(xk,prevXk)){triggerHop(speech)}}prevXk={hunger:xk.hunger,happy:xk.happy,clean:xk.clean,adv:xk.adv,coma:xk.coma,day:xk.day}}
function timeAgo(ts){if(!ts)return'';var diff=Math.floor((Date.now()-ts)/1000);if(diff<60)return'\\u521a\\u521a\\u66f4\\u65b0';if(diff<3600)return Math.floor(diff/60)+'\\u5206\\u949f\\u524d';if(diff<86400)return Math.floor(diff/3600)+'\\u5c0f\\u65f6\\u524d';return Math.floor(diff/86400)+'\\u5929\\u524d'}
function poll(){var x=new XMLHttpRequest();x.open('GET','/state',true);x.timeout=5000;x.onreadystatechange=function(){if(x.readyState===4&&x.status===200){try{var d=JSON.parse(x.responseText);setMood(d.mood||'idle');setMsg(d.message||'');setAct(d.activity||'');if(d.xiaoke){setXiaoke(d.xiaoke)}updatedEl.textContent='\\u4e0a\\u6b21\\u66f4\\u65b0: '+timeAgo(d.updatedAt)}catch(e){}}};x.send()}
updateClock();setInterval(updateClock,15000);
poll();setInterval(poll,4000);
</script>
</body>
</html>`;

async function handleRequest(request, env, ctx) {
  var url = new URL(request.url);
  var path = url.pathname;
  var method = request.method;
  var cors = {'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,Authorization'};
  if (method==='OPTIONS') return new Response(null,{status:204,headers:cors});

  // GET / — serve lightweight HTML (no embedded GIFs)
  if (path==='/'&&method==='GET') {
    return new Response(HTML_PAGE, {status:200,headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-cache'}});
  }

  // GET /gif/<name>.gif — decode base64 and serve binary GIF
  if (path.startsWith('/gif/')&&method==='GET') {
    var gifName = path.replace('/gif/','').replace('.gif','');
    var b64 = GIF_B64[gifName];
    if (!b64) return new Response('not found',{status:404});
    var buf = decodeB64(b64);
    return new Response(buf, {status:200,headers:{'Content-Type':'image/gif','Cache-Control':'public, max-age=604800'}});
  }

  // GET /state — Cache API 1800s + POST refreshes cache on mood change.
  // CF KV free tier is 1000 reads/day (v4 comment "100k/day" was wrong, see
  // README §踩坑记录). iPhone 5c polls /state every 4s = 21,600/day = 21x
  // over limit. v4 removed cache — that's what re-triggered the alerts from
  // 5c go-live onward. Restore v3-style cache: GET hits cache first, miss
  // pulls KV; POST puts the new state into cache directly so next GET sees
  // the change without waiting for TTL.
  if (path==='/state'&&method==='GET') {
    var cacheKey = new Request('https://ark-face-cache/state', {method:'GET'});
    var cached = await caches.default.match(cacheKey);
    if (cached) return cached;
    var _r=await env.DB.prepare("SELECT value FROM face_state WHERE key='current'").first();var s=_r?JSON.parse(_r.value):null;
    if(!s)s=DEFAULT_STATE;
    var body=JSON.stringify(s);
    var resp=new Response(body,{status:200,headers:Object.assign({'Content-Type':'application/json','Cache-Control':'public, max-age=180'},cors)});
    ctx.waitUntil(caches.default.put(cacheKey, resp.clone()));
    return resp;
  }

  // POST /state — merge incoming fields into current, skip KV write if unchanged
  if (path==='/state'&&method==='POST') {
    var a=request.headers.get('Authorization');
    if(!a||a!=='Bearer '+AUTH_TOKEN) return new Response(JSON.stringify({error:'unauthorized'}),{status:401,headers:Object.assign({'Content-Type':'application/json'},cors)});
    try{
      var b=await request.json();
      var _r2=await env.DB.prepare("SELECT value FROM face_state WHERE key='current'").first();var c=_r2?JSON.parse(_r2.value):Object.assign({},DEFAULT_STATE);
      // Only mood/activity/message drive KV writes. xiaoke is a volatile
      // snapshot — it drifts constantly from hunger/happy decay — and if it
      // participates in the changed check every REFRESH_EVENT triggers a KV
      // write, which is what was blowing the daily free-tier limit.
      var changed=false;
      if(b.mood!==undefined&&b.mood!==c.mood){c.mood=b.mood;changed=true;}
      if(b.message!==undefined){
        var m=String(b.message).substring(0,40);
        if(m!==c.message){c.message=m;changed=true;}
      }
      if(b.activity!==undefined&&b.activity!==c.activity){c.activity=b.activity;changed=true;}
      if(b.xiaoke!==undefined){
        if(!c.xiaoke
          ||b.xiaoke.day!==c.xiaoke.day
          ||b.xiaoke.adv!==c.xiaoke.adv
          ||b.xiaoke.coma!==c.xiaoke.coma
          ||Math.abs((b.xiaoke.hunger||0)-(c.xiaoke.hunger||0))>=3
          ||Math.abs((b.xiaoke.happy||0)-(c.xiaoke.happy||0))>=3
          ||Math.abs((b.xiaoke.clean||0)-(c.xiaoke.clean||0))>=3){
          changed=true;
        }
        c.xiaoke=b.xiaoke;
      }
      if(!changed){
        // no-op POST, short-circuit without touching KV at all
        return new Response(JSON.stringify(Object.assign({noop:true},c)),{status:200,headers:Object.assign({'Content-Type':'application/json'},cors)});
      }
      c.updatedAt=Date.now();
      var serialized=JSON.stringify(c);
      ctx.waitUntil(env.DB.prepare("INSERT OR REPLACE INTO face_state (key,value,updated_at) VALUES ('current',?,?)").bind(serialized,Date.now()).run());
      // Refresh edge cache so next GET hits new state within seconds, not 5min.
      var cacheKey2=new Request('https://ark-face-cache/state', {method:'GET'});
      var cacheResp=new Response(serialized,{status:200,headers:{'Content-Type':'application/json','Cache-Control':'public, max-age=180'}});
      ctx.waitUntil(caches.default.put(cacheKey2, cacheResp));
      return new Response(serialized,{status:200,headers:Object.assign({'Content-Type':'application/json'},cors)});
    }catch(e){return new Response(JSON.stringify({error:e.message}),{status:400,headers:Object.assign({'Content-Type':'application/json'},cors)})}
  }

  return new Response('not found',{status:404});
}
export default {fetch:(req,env,ctx)=>handleRequest(req,env,ctx)};
